window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-36001\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥίνη, ης</h1><div class=\"entry-meta\"><span>DGP · ordem 169 na letra ρ · nº geral 36001</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ῥινῆ, ῆς (ἡ) lima.</p></section></article>\n<article id=\"entry-dgp-36002\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥινηλατέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 170 na letra ρ · nº geral 36002</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">seguir a pista farejando; farejar. 〈ῥίς, ἐλαύνω〉</p></section></article>\n<article id=\"entry-dgp-36003\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥινόκερως, ωτος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 171 na letra ρ · nº geral 36003</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rinoceronte. 〈ῥίς, κέρας〉</p></section></article>\n<article id=\"entry-dgp-36004\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥινόν, οῦ (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 172 na letra ρ · nº geral 36004</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pele; couro 2 escudo (de couro, de pele).</p></section></article>\n<article id=\"entry-dgp-36005\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥινός1, οῦ (ἡ</h1><div class=\"entry-meta\"><span>DGP · ordem 173 na letra ρ · nº geral 36005</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ὁ) 1 pele de homem ou de animal, vivo ou morto 2 escudo de pele ou de couro 3 pl. correias das luvas de pugilista.</p></section></article>\n<article id=\"entry-dgp-36006\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥινός2</h1><div class=\"entry-meta\"><span>DGP · ordem 174 na letra ρ · nº geral 36006</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. de ῥίς.</p></section></article>\n<article id=\"entry-dgp-36007\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥινόσιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 175 na letra ρ · nº geral 36007</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de nariz chato. 〈ῥίς, σιμός〉</p></section></article>\n<article id=\"entry-dgp-36008\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥινοτόρος, ος, ον,</h1><div class=\"entry-meta\"><span>DGP · ordem 176 na letra ρ · nº geral 36008</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que traspassa os escudos, o couro do escudos, epít. de Ares. 〈ῥινός, τείρω〉</p></section></article>\n<article id=\"entry-dgp-36009\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 177 na letra ρ · nº geral 36009</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cume; cimo; pico 2 ponta; promontório 3 golfo; baía formado por um promontório.</p></section></article>\n<article id=\"entry-dgp-36010\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥιπή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 178 na letra ρ · nº geral 36010</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 arremesso; lançamento; lance (de dardos, do olhar) 2 movimento dos pés, ao andar 3 o bater de asas 4 o piscar de olhos 5 força de um corpo lançado; impulso; ímpeto: ῥ. πυρός hom. ímpeto do fogo 6 emanação: ῥ. οἴνου pínd. odor do vinho, παμφεγγεῖς ἄστρων ῥιπαί sóf. raios luminosos dos astros. 〈ῥίπτω〉</p></section></article>\n<article id=\"entry-dgp-36011\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥιπίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 179 na letra ρ · nº geral 36011</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 abanar 2 agitar; sacudir 3 soprar para atiçar (fogo) 4 excitar; alimentar (discórdia). 〈ῥιπίς〉</p></section></article>\n<article id=\"entry-dgp-36012\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥιπίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 180 na letra ρ · nº geral 36012</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fole (para atiçar o fogo) 2 leque; abanador. 〈ῥίπτω〉</p></section></article>\n<article id=\"entry-dgp-36013\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥῖπος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 181 na letra ρ · nº geral 36013</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ῥίψ.</p></section></article>\n<article id=\"entry-dgp-36014\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥιπτάζεσκεν</h1><div class=\"entry-meta\"><span>DGP · ordem 182 na letra ρ · nº geral 36014</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª sing. impf. iter. de ῥιπτάζω.</p></section></article>\n<article id=\"entry-dgp-36015\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥιπτάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 183 na letra ρ · nº geral 36015</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 agitar em todos os sentidos ou sem cessar; pôr em movimento; sacudir; agitar; mover algo, dat.: ὀφρύσι ῥιπτάζειν hin. mover sem cessar as sobrancelhas 2 com ou sem ἑαυτόν, sacudir-se, agitar-se sem cessar; estar inquieto, agitado. 〈ῥίπτω〉</p></section></article>\n<article id=\"entry-dgp-36016\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥίπτασκον</h1><div class=\"entry-meta\"><span>DGP · ordem 184 na letra ρ · nº geral 36016</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">impf. iter. de ῥίπτω.</p></section></article>\n<article id=\"entry-dgp-36017\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥιπτασμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 185 na letra ρ · nº geral 36017</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 agitação contínua; agitação; perturbação 2 Medic. convulsão 3 inquietude. 〈ῥιπτάζω〉</p></section></article>\n<article id=\"entry-dgp-36018\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥιπταστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 186 na letra ρ · nº geral 36018</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se agita ou se inquieta facilmente. 〈ῥιπτάζω〉</p></section></article>\n<article id=\"entry-dgp-36019\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥιπτεῦσι</h1><div class=\"entry-meta\"><span>DGP · ordem 187 na letra ρ · nº geral 36019</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. pres. at. jôn. de ῥιπτέω.</p></section></article>\n<article id=\"entry-dgp-36020\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥιπτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 188 na letra ρ · nº geral 36020</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) cf. ῥίπτω.</p></section></article>\n<article id=\"entry-dgp-36021\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥιπτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 189 na letra ρ · nº geral 36021</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jogado; lançado; precipitado. 〈ῥίπτω〉</p></section></article>\n<article id=\"entry-dgp-36022\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥίπτω</h1><div class=\"entry-meta\"><span>DGP · ordem 190 na letra ρ · nº geral 36022</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἔρριπτον, fut. ῥίψω, aor. ἔρριψα, perf. ἔρριφα; pas. fut.2 ῥιφήσομαι, aor. ἐρρίφθην, aor.2 ἐρ­ρίφην, perf. ἐρρίμμαι, m.-q.-perf. ἐρρίμην, fut. ant. ἐρρίψομαι) 1 lançar; jogar uma coisa ou pessoa, ac., contra ou sobre outra, πρός e ac., sobre alguém, ἐπί e dat. ou ac., ou gen.: ῥ. νεανίας λόγους ἐς ἡμᾶς eur. lançar palavras insensatas contra nós, ῥ. ἀρὰς Ἀχαιοῖς eur. lançar imprecações contra os aqueus 2 lançar; atirar; precipitar alguém, ac., do alto de, ἀπό, κατά e gen.: ῥ. δέμας κύνεσσιν a.p. jogar um cadáver aos cães, ῥ. τινὰ ἐς τὸ δυστυχές ésql. lançar alguém na infelicidade 3 arrojar; deixar cair; lançar: ῥ. κλῆρον plat. lançar a sorte, ῥ. κίνδυνον eur. correr um risco, expor-se ao perigo 4 repelir; expulsar: ῥῖψίν με γῆς ἐκ τῆσδε sóf. expulsa-me desta terra 5 rejeitar; abandonar (criança, escudo); desfazer-se de, ac. ♦ com ou sem ἑαυτόν 6 lançar-se; jogar-se; precipitar-se: ῥ. ἑαυτὸν ἀπὸ πέτρας ésql. lançar-se de um rochedo, ῥ. ἑαυτὸν χθονί sóf. jogar-se no chão, ῥ. εἰς τὴν θάλασσαν her. lançar-se ao mar 7 lançar-se para morrer; matar-se lançando-se de uma altura 8 Medic. (doente) debater-se; estar agitado 9 entregar-se a, εἰς e ac. ou ἐν e dat.: ῥ. ἑαυτὸν εἰς ἐλπίδας ἀπόρους plut. entregar-se a vãs esperanças, ῥ. ἐν πένθει eur. entregar-se ao sofrimento.</p></section></article>\n<article id=\"entry-dgp-36023\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥίς, ῥινός (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 191 na letra ρ · nº geral 36023</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 nariz 2 pl. narinas 3 tromba; focinho; bico.</p></section></article>\n<article id=\"entry-dgp-36024\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥιφέσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 192 na letra ρ · nº geral 36024</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut.2 pas. de ῥίπτω.</p></section></article>\n<article id=\"entry-dgp-36025\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥίψ, ῥιπός (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 193 na letra ρ · nº geral 36025</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 caniço 2 treliça de caniço 3 vime 4 grade de vime 5 esteira (de palha, de vime).</p></section></article>\n<article id=\"entry-dgp-36026\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥίψαι, ῥίψω</h1><div class=\"entry-meta\"><span>DGP · ordem 194 na letra ρ · nº geral 36026</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ῥίπτω.</p></section></article>\n<article id=\"entry-dgp-36027\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥίψασπις, ιδος</h1><div class=\"entry-meta\"><span>DGP · ordem 195 na letra ρ · nº geral 36027</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) que joga o escudo para fugir; desertor; covarde. 〈ῥίπτω, ἀσπίς〉</p></section></article>\n<article id=\"entry-dgp-36028\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥῖψις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 196 na letra ρ · nº geral 36028</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de lançar; lançamento: ῥίψεις ὀμμάτων plut. golpes de vista 2 emissão: ῥ. τοῦ σπέρ­ματος artt. ejaculação de sêmen 3 o processo de ser lançado: Ἡφαίστου ῥίψεις ὑπὸ πατρός plat. a queda de Hefesto, lançado pelo pai. 〈ῥίπτω〉</p></section></article>\n<article id=\"entry-dgp-36029\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥιψοκίνδυνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 197 na letra ρ · nº geral 36029</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se lança ao perigo; temerário (pessoa) 2 arriscado; perigoso (ação) ♦ τὸ ῥιψοκίνδυνον 3 audácia; temeridade. 〈ῥίπτω, κίνδυνος〉</p></section></article>\n<article id=\"entry-dgp-36030\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥίψοπλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 198 na letra ρ · nº geral 36030</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que joga suas armas; que deserta; covarde. 〈ῥίπτω, ὅπλον〉</p></section></article>\n<article id=\"entry-dgp-36031\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 199 na letra ρ · nº geral 36031</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = ῥοή.</p></section></article>\n<article id=\"entry-dgp-36032\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοδανός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 200 na letra ρ · nº geral 36032</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">leve; flexível.</p></section></article>\n<article id=\"entry-dgp-36033\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥόδεος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 201 na letra ρ · nº geral 36033</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de rosa 2 feito de rosa 3 semelhante à rosa; róseo 4 de cor de rosa. 〈ῥόδον〉 Ῥόδη, ης (ἡ) Rode, n. de m. 〈ῥόδον〉 Ῥόδιος, α, ον 1 de Rodes; ródio ♦ οἱ Ῥόδιοι 2 os ródios. 〈 Ῥόδος〉</p></section></article>\n<article id=\"entry-dgp-36034\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοδοδάκτυλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 202 na letra ρ · nº geral 36034</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de dedos róseos, epít. de Aurora e de Afrodite. 〈ῥόδον, δάκτυλος〉</p></section></article>\n<article id=\"entry-dgp-36035\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοδοδάφνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 203 na letra ρ · nº geral 36035</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">loureiro rosa. 〈ῥόδον, δάφνη〉</p></section></article>\n<article id=\"entry-dgp-36036\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοδόεις, όεσσα, όεν</h1><div class=\"entry-meta\"><span>DGP · ordem 204 na letra ρ · nº geral 36036</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de rosa; róseo 2 de cor rosa 3 coberto de rosas. 〈ῥόδον〉</p></section></article>\n<article id=\"entry-dgp-36037\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥόδον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 205 na letra ρ · nº geral 36037</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rosa 2 jardim de rosas.</p></section></article>\n<article id=\"entry-dgp-36038\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοδόπαχυς</h1><div class=\"entry-meta\"><span>DGP · ordem 206 na letra ρ · nº geral 36038</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = ῥοδόπηχυς.</p></section></article>\n<article id=\"entry-dgp-36039\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοδόπηχυς, υς, υ</h1><div class=\"entry-meta\"><span>DGP · ordem 207 na letra ρ · nº geral 36039</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. εος de braços róseos, ger. epít. de divindade. 〈ῥόδον, πῆχυς〉 Ῥόδος, ου (ἡ) 1 Rodes, ilha grega 2 Rodo, ninfa.</p></section></article>\n<article id=\"entry-dgp-36040\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοδωνιά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 208 na letra ρ · nº geral 36040</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 jardim de rosas 2 canteiro de rosas; roseiral. 〈ῥόδον〉</p></section></article>\n<article id=\"entry-dgp-36041\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 209 na letra ρ · nº geral 36041</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 curso d’água: ῥ. Ὠκεανοῖο hom. curso do Oceano 2 escoamento (de líquido); fluxo 3 sumo; suco: ἀμπέλου ῥ. eur. suco da vinha, vinho 4 curso dos acontecimentos ou do destino; vicissitude 5 fluxo do tempo 6 fluxo; sequência: ἐπέων ῥοαί pínd. o fluir dos versos.</p></section></article>\n<article id=\"entry-dgp-36042\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοθέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 210 na letra ρ · nº geral 36042</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 zumbar como ondas que se chocam: λόγοι δ’ἐν ἀλλήλοισιν ἐρρόθουν κακοί sóf. os palavrões troavam entre uns e outros 2 murmurar: ἄνδρες ἐρρόθουν ἐμοί sóf. homens murmuravam contra mim 3 tr. lançar ruidosamente. 〈ῥόθος〉</p></section></article>\n<article id=\"entry-dgp-36043\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοθίας, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 211 na letra ρ · nº geral 36043</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) = ῥόθιος.</p></section></article>\n<article id=\"entry-dgp-36044\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥόθιος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 212 na letra ρ · nº geral 36044</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e α, ον 1 que se bate ruidosamente; que fere ruidosamente as ondas (navio) 2 que come fazendo ruído (porco); ruidoso 3 impetuoso (cavalo) 4 fragoroso; rumorejante ♦ τὸ ῥόθιον 5 choque ruidoso das vagas; ruído das vagas 6 pl. ondas que se quebram 7 batida dos remos; barulho do remos 8 ruído da cavalaria; estrépito 9 ruído dos aplausos; aplauso; aclamação 10 tumulto 11 movimento impetuoso; ímpeto. 〈ῥόθος〉</p></section></article>\n<article id=\"entry-dgp-36045\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥόθος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 213 na letra ρ · nº geral 36045</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 barulho do bater das ondas; barulho das vagas; rumor; fragor 2 barulho dos remos que ferem as ondas; batida dos remos 3 ruído de asas 4 barulho de pancada 5 barulho tumultuoso; rumor confuso; clamor 6 movimento rápido; batida 7 rastro; pegada.</p></section></article>\n<article id=\"entry-dgp-36046\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοιά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 214 na letra ρ · nº geral 36046</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 romãzeira 2 romã.</p></section></article>\n<article id=\"entry-dgp-36047\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοιβδέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 215 na letra ρ · nº geral 36047</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e aor. ἐρροίβδησα) 1 intr. tragar como sorvedouro; sorver em redemoinho 2 intr. (vento) assobiar; sibilar 3 tr. agitar com barulho estridente, fazer vibrar terrivelmente. 〈ῥοῖβδος〉</p></section></article>\n<article id=\"entry-dgp-36048\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοίβδησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 216 na letra ρ · nº geral 36048</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ruído estridente; sibilo; silvo. 〈ῥοιβδέω〉</p></section></article>\n<article id=\"entry-dgp-36049\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοίβδος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 217 na letra ρ · nº geral 36049</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">barulho estridente; barulho que retine.</p></section></article>\n<article id=\"entry-dgp-36050\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοιζέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 218 na letra ρ · nº geral 36050</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. desus., aor. ἐρροίζησα, perf. desus., m.-q.-perf. pas. ἐρροιζήμην) 1 assobiar para alguém, dat. 2 fazer silvar; atirar (dardo) 3 romper (o ar), ac., com um barulho estridente ♦ méd. pas. 4 voar silvando. 〈ῥοῖζος〉</p></section></article>\n<article id=\"entry-dgp-36051\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοιζηδόν</h1><div class=\"entry-meta\"><span>DGP · ordem 219 na letra ρ · nº geral 36051</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com um estrondo; rumorosamente; sibilando, silvando com ímpeto.</p></section></article>\n<article id=\"entry-dgp-36052\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοίζημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 220 na letra ρ · nº geral 36052</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 barulho estridente; fragor 2 movimento impetuoso; impetuosidade. 〈ῥοιζέω〉</p></section></article>\n<article id=\"entry-dgp-36053\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοῖζος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 221 na letra ρ · nº geral 36053</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 som estridente; som agudo; assobio; sibilo (de flecha, vento, flauta) 2 marulho de água corrente 3 ruído de asas que batem 4 estrépito; estrondo; zumbido 5 movimento impetuoso; arremesso; ímpeto.</p></section></article>\n<article id=\"entry-dgp-36054\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοιζώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 222 na letra ρ · nº geral 36054</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ruidoso; impetuoso. 〈ῥοῖζος, ωδης〉</p></section></article>\n<article id=\"entry-dgp-36055\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοιή</h1><div class=\"entry-meta\"><span>DGP · ordem 223 na letra ρ · nº geral 36055</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ῥοιά.</p></section></article>\n<article id=\"entry-dgp-36056\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοικός1, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 224 na letra ρ · nº geral 36056</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 curvo; recurvado; torto; arqueado (perna) ♦ τὸ ῥοικόν 2 curvatura da perna.</p></section></article>\n<article id=\"entry-dgp-36057\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοικός2, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 225 na letra ρ · nº geral 36057</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 flácido; mole 2 crist. transitório; perecível 3 Medic. que sofre de fluxo (diarréia ou menstruação). 〈ῥόος〉</p></section></article>\n<article id=\"entry-dgp-36058\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥομβέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 226 na letra ρ · nº geral 36058</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fazer girar o ῥόμβος.</p></section></article>\n<article id=\"entry-dgp-36059\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥομβοειδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 227 na letra ρ · nº geral 36059</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 com forma de losango; romboidal ♦ τὸ Ῥομβοιδές 2 monumento em forma de losango, em Mégara. 〈ῥόμβος, εἶδος〉</p></section></article>\n<article id=\"entry-dgp-36060\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥόμβος,</h1><div class=\"entry-meta\"><span>DGP · ordem 228 na letra ρ · nº geral 36060</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. ῥύμβος, ου (ὁ) 1 rombo, disco que se faz ressoar fazendo-o girar à volta de uma corda durante os Mistérios 2 roda mágica; disco para encantamento 3 tamborim; tímpano usado no culto de Dioniso 4 pião, brinquedo 5 Medic. atadura em forma de rombo 6 Geom. rombo; losango 7 movimento vibratório ou rotatório; arremesso. 〈ῥέμβω〉</p></section></article>\n<article id=\"entry-dgp-36061\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥομβώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 229 na letra ρ · nº geral 36061</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ῥομβοειδής. 〈ῥόμβος, ωδης〉</p></section></article>\n<article id=\"entry-dgp-36062\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥομφαία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 230 na letra ρ · nº geral 36062</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sabre longo de dois gumes usado pelos trácios 2 bíbl. sabre; espada.</p></section></article>\n<article id=\"entry-dgp-36063\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥόος-ῥοῦς, ῥόου-ῥοῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 231 na letra ρ · nº geral 36063</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 correnteza (de rio, de mar): κατὰ ῥόον hom., át. κατὰ ῥοῦν a favor da correnteza, ao sabor da corrente, κατὰ ῥοῦν ἡ ναῦς ἐφέρετο long. a nau ia à deriva 2 corrente de ar: ῥ. καπνοῦ pínd. coluna de fumaça 3 Medic. fluxo dos humores (intestinal, menstrual) 4 curso, fluxo das coisas: κατὰ ῥοῦν plat. sem obstáculo, de modo feliz. 〈ῥέω〉</p></section></article>\n<article id=\"entry-dgp-36064\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥόπαλον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 232 na letra ρ · nº geral 36064</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bastão grosso; bordão 2 maça; clava usada como arma de guerra 3 martelo 4 aldrava 5 verga; vara 6 membro viril. 〈ῥέπω〉</p></section></article>\n<article id=\"entry-dgp-36065\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοπή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 233 na letra ρ · nº geral 36065</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 movimento de cima para baixo; inclinação 2 inclinação de uma balança: διαστρέφειν τὴν ῥοπήν plut. alterar a inclinação da balança 3 o que determina a inclinação; peso: ὡς τοῖσδε καὶ δὶς ἀντισηκῶσαι ῥοπῇ ésql. de maneira a igualar duas vezes seu peso 4 momento crítico, decisivo: ἐν ῥοπῇ τοιᾷδε κείμενος sóf. achando-se nessa situação crítica, ἐπὶ μιᾶς ῥοπῆς εἶναι tuc. só ter uma chance a correr, ῥοπή μοι βίου sóf. o momento supremo de minha vida 5 causa ou circunstância determinante; influência: ἐπὶ σμικρᾶς ῥοπῆς eur. sob uma pequena influência, i.e., por um nada 6 peso; importância: ῥοπὴν ποιεῖν teofr. produzir peso, ῥοπὴν ἔχειν dem. ter peso, não ser sem importância, οὐ μικράν τινα αὐτῶν ῥοπὴν εἶναι καὶ παρόντων καὶ ἀνόντων xen. seu peso não pequeno (era muito importante), estivessem eles presentes ou ausentes, μεγάλη ἔσται ῥοπὴ εἰ isócr. importava muito que, μικραὶ δυνάμεις μεγάλας τὰς πορὰς ἐποίησαν isócr. pequenas influências constituem grande peso 7 alternativa: βλέπω δύο ῥοπάς· ἢ θανεῖν ἢ πατρίδα τ’ἐλθεῖν eur. vejo duas alternativas: ou morrer ou voltar para a pátria 8 reviravolta; mudança: ῥοπὴν ποιεῖν causar reviravolta. 〈ῥέπω〉</p></section></article>\n<article id=\"entry-dgp-36066\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥόπτρον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 234 na letra ρ · nº geral 36066</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aldrava 2 gatilho de armadilha; armadilha 3 martelo 4 clava 5 tamborim dos Coribantes e dos sacerdotes de Cibele 6 tambor. 〈ῥέπω〉</p></section></article>\n<article id=\"entry-dgp-36067\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοῦς</h1><div class=\"entry-meta\"><span>DGP · ordem 235 na letra ρ · nº geral 36067</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ρόος. Ῥοῦφος, ου (ὁ) Rufo, n. de h. [lat.]</p></section></article>\n<article id=\"entry-dgp-36068\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοφέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 236 na letra ρ · nº geral 36068</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ὀρρόφουν, fut. ῥοφήσω e ῥοφήσομαι, aor. ἐρρόφησα, perf. desus., aor. pas. ἐρροφήθην) 1 engolir vorazmente; engolir de um só gole; sorver algo, ac. ou gen. partit. 2 devorar 3 consumir; esvaziar (uma taça); exaurir ♦ méd. 4 Medic. alimentar-se com papa ou líquido.</p></section></article>\n<article id=\"entry-dgp-36069\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥόφημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 237 na letra ρ · nº geral 36069</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mingau; papa; sopa. 〈ῥοφέω〉</p></section></article>\n<article id=\"entry-dgp-36070\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοχθέω</h1><div class=\"entry-meta\"><span>DGP · ordem 238 na letra ρ · nº geral 36070</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf. ép. 3ª sing. ῥόχθεν) 1 (ondas) bater com fragor; bramir ao quebrar-se 2 ressoar; ribombar sob o choque das ondas.</p></section></article>\n<article id=\"entry-dgp-36071\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥοώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 239 na letra ρ · nº geral 36071</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que tem correnteza forte; que corre impetuosamente 2 exposto a forte correnteza (promontório) 3 irrigado por água corrente (lugar) 4 Medic. que apresenta fluxo de humores ou supuração (doença) 5 Medic. que sofre de algum fluxo (pessoa) 6 que tende a cair; que está para cair (fruto) 7 crist. transitório ♦ τὸ ῥοῶδες 8 corrente impetuosa; altura de onde escorrem as águas 9 umidade; humor. 〈ῥόος, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-36072\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥύαξ, ακος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 240 na letra ρ · nº geral 36072</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 curso de água impetuoso; corrente 2 torrente de água da chuva; enxurrada 3 torrente de lava 4 torrente; enxurrada; grande quantidade (de dinheiro) 5 conduto; canal. 〈ρέω〉</p></section></article>\n<article id=\"entry-dgp-36073\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυάς, άδος</h1><div class=\"entry-meta\"><span>DGP · ordem 241 na letra ρ · nº geral 36073</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem., n.) 1 que corre; que escorre; que flui 2 que cai (cabelo, fruto) 3 que é flácido; mole ♦ ἡ ῥυάς 4 Medic. lacrimejamento, doença ♦ οἱ ῥυάδες 5 Zool. peixes que emigram em cardumes. 〈ῥέω〉</p></section></article>\n<article id=\"entry-dgp-36074\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥύατο</h1><div class=\"entry-meta\"><span>DGP · ordem 242 na letra ρ · nº geral 36074</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ῥύομαι.</p></section></article>\n<article id=\"entry-dgp-36075\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυάχετος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 243 na letra ρ · nº geral 36075</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">com. populacho; povaréu. 〈ῥύαξ〉</p></section></article>\n<article id=\"entry-dgp-36076\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥύγχος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 244 na letra ρ · nº geral 36076</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 focinho de porco, de cão 2 bico de ave.</p></section></article>\n<article id=\"entry-dgp-36077\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυγχίον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 245 na letra ρ · nº geral 36077</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dim. de ῥύγχος.</p></section></article>\n<article id=\"entry-dgp-36078\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥύδην</h1><div class=\"entry-meta\"><span>DGP · ordem 246 na letra ρ · nº geral 36078</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. = ῥυδόν.</p></section></article>\n<article id=\"entry-dgp-36079\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυδόν</h1><div class=\"entry-meta\"><span>DGP · ordem 247 na letra ρ · nº geral 36079</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. abundantemente; em grande número; prodigamente. 〈ῥέω, -δον〉</p></section></article>\n<article id=\"entry-dgp-36080\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυείς, εῖσα, έν</h1><div class=\"entry-meta\"><span>DGP · ordem 248 na letra ρ · nº geral 36080</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor. de ῥέω.</p></section></article>\n<article id=\"entry-dgp-36081\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥύη, ῥυῆναι</h1><div class=\"entry-meta\"><span>DGP · ordem 249 na letra ρ · nº geral 36081</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ῥέω.</p></section></article>\n<article id=\"entry-dgp-36082\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυθμίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 250 na letra ρ · nº geral 36082</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 dispor em intervalos regulares algo, ac. 2 dispor, regular segundo uma ordem; regrar (a vida); compor (a fisionomia) 3 determinar; estabelecer 4 disciplinar; dirigir; orientar; educar (crianças) 5 tratar; dispensar tratamento (bom ou mal) a alguém, ac. 6 regular segundo um ritmo; ritmar; cadenciar 7 Métr. escandir 8 cuidar da aparência; cultivar cuidados ao corpo: ὑποχρίουσι τε καὶ ἐντρίβουσιν αὐτοὺς καὶ τἆλλα ῥυθμίζουσι xen. [criados de quarto] pintam os olhos, maquiam-se e cultivam os demais cuidados à aparência ♦ méd. 9 ajeitar (os cabelos). 〈ῥυθμός〉</p></section></article>\n<article id=\"entry-dgp-36083\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυθμικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 251 na letra ρ · nº geral 36083</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 relativo ao ritmo; do ritmo 2 em conformidade com o ritmo; rítmico 3 hábil em ritmar (pessoa). 〈ῥυθμός〉</p></section></article>\n<article id=\"entry-dgp-36084\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυθμοποιΐα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 252 na letra ρ · nº geral 36084</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ordenamento rítmico. 〈ῥυθμοποιός〉</p></section></article>\n<article id=\"entry-dgp-36085\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυθμοποιός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 253 na letra ρ · nº geral 36085</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que ordena de acordo com o ritmo; que regula a medida rítmica. 〈ῥυθμός, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-36086\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυθμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 254 na letra ρ · nº geral 36086</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 movimento regrado e medido; ritmo; tempo; cadência: τῇ τῆς κινήσεως τάξει ῥ. ὄνομα plat. o nome para a regularidade do movimento é ritmo, μετὰ μουσικῆς καὶ ῥυθμῶν isócr. com música e ritmo, ἀποδιδόναι τῇ λέξει ἁρμονίαν καὶ ῥυθμόν plat. conferir à elocução harmonia e ritmo 2 disposição regular das partes ou dos elementos; justa proporção; harmonia; regularidade; simetria: κατὰ αὐτὸν ῥυθμόν plat. segundo a mesma regra 3 maneira de ser; condição (de homem); natureza; temperamento 4 figura; disposição; forma: μετέβαλον τὸν ῥυθμὸν τῶν γραμμάτων her. mudaram a forma das letras. 〈ῥέω〉</p></section></article>\n<article id=\"entry-dgp-36087\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥῦμα1, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 255 na letra ρ · nº geral 36087</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 arremesso 2 alcance de um arremesso: ἐκ τόξου ῥύματος xen. no alcance de um arremesso de flecha 3 cordame; cabo (para reboque). 〈ἐρύω〉</p></section></article>\n<article id=\"entry-dgp-36088\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥῦμα2, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 256 na letra ρ · nº geral 36088</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">abrigo; refúgio. 〈ῥύομαι〉</p></section></article>\n<article id=\"entry-dgp-36089\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥῦμα3, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 257 na letra ρ · nº geral 36089</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. curso de água; corrente. 〈ῥέω〉</p></section></article>\n<article id=\"entry-dgp-36090\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥύμη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 258 na letra ρ · nº geral 36090</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 força; ímpeto; curso rápido; impulso; veemência (de algo em movimento, de das paixões): ῥ. τοῦ αἵματος hipócr. fluxo do sangue, ῥ. τῆς ὀργῆς dem. ímpeto de cólera 2 impulso (da sorte); favor da sorte 3 Mil. quartel de um regimento romano 4 Mil. batalhão de um quartel 5 tard. rua; viela.</p></section></article>\n<article id=\"entry-dgp-36091\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥύμμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 259 na letra ρ · nº geral 36091</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sabão; lixívia; barrela 2 imundície; sujeira; nódoa. 〈ῥύπτω〉</p></section></article>\n<article id=\"entry-dgp-36092\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 260 na letra ρ · nº geral 36092</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 timão de carro 2 tirante; rédea de parelha de carro 3 cauda de cometa.</p></section></article>\n<article id=\"entry-dgp-36093\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυντάκης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 261 na letra ρ · nº geral 36093</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pássaro das Índias do tamanho de uma pomba.</p></section></article>\n<article id=\"entry-dgp-36094\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυοίατο</h1><div class=\"entry-meta\"><span>DGP · ordem 262 na letra ρ · nº geral 36094</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. opt. jôn. de ῥυόμαι.</p></section></article>\n<article id=\"entry-dgp-36095\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥύομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 263 na letra ρ · nº geral 36095</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(impf. ἐρρυόμην, fut. ῥύσομαι, aor. ἐρρυσάμην, perf. desus.) 1 reter; segurar: Ἠῶ δ’ αὖτε ῥύσατ’ ἐπ’ Ὠκεανῷ hom. [Atena] reteve Aurora junto ao Oceano 2 afastar de um perigo; preservar; proteger; salvar algo ou alguém, ac., de algo ou alguém, gen. ou ἐκ, ἀπό e gen., ou inf. com ou sem μή: ἀθανάτων ὅς τίς σε φυλάσσει τε ῥύεταί τε hom. aquele dos imortais que te guarda e protege, οἵ τε πτολίεθρα ῥύονται hom. os que defendem a cidade, κακῶν μυρίων ἐρρύετο eur. de uma infinidade de males [Alceste nos] preservava, ἀλλὰ σὺ ῥῦσαι ὑπ’ ἠέρος υἷας Ἀχαιῶν hom. vamos, salva da bruma os filhos dos aqueus, ὃν θανεῖν ἐρρυσάμην eur. a quem salvei de morrer 3 isolar; esconder; encobrir; ocultar: ὡς ῥύσαιτο περὶ χροῒ μήδεα φωτός hom. a fim de que ocultasse da luz o membro viril 4 afastar; repelir: ῥ. κῆρα μέλαινα hom. afastar o negro destino.</p></section></article>\n<article id=\"entry-dgp-36096\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυπαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 264 na letra ρ · nº geral 36096</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. at. e pas. e aor. pas. ἐρρυπάνθην) 1 manchar; macular; desfigurar 2 ofender; ultrajar 3 ofuscar (a felicidade) ♦ pas. 3 sujar-se; emporcalhar-se. 〈ῥύπος〉</p></section></article>\n<article id=\"entry-dgp-36097\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυπαρεύομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 265 na letra ρ · nº geral 36097</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. ser sórdido; ser imundo, impuro. 〈ῥυπαρός〉</p></section></article>\n<article id=\"entry-dgp-36098\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυπαρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 266 na letra ρ · nº geral 36098</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sujeira 2 avareza sórdida. 〈ῥυπαρός〉</p></section></article>\n<article id=\"entry-dgp-36099\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυπαρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 267 na letra ρ · nº geral 36099</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sujo; imundo 2 sórdido; mesquinho 3 grosseiro; rude; inculto. 〈ῥύπος〉</p></section></article>\n<article id=\"entry-dgp-36100\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ῥυπάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 268 na letra ρ · nº geral 36100</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. ép. ῥυπόω e impf. ἐρρύπων) 1 ser sujo, imundo 2 ser sórdido. 〈ῥύπος〉</p></section></article>\n";
